"use strict";const p=/^#?(?:[0-9a-f]{3}|[0-9a-f]{4}|[0-9a-f]{6}|[0-9a-f]{8})$/i;export function hexToRgba(n,s){if(!p.test(n))throw new Error(`Invalid hex color: ${n}`);const e=n.startsWith("#")?n.slice(1):n,t=e.length===3||e.length===4?e.split("").map(o=>o+o).join(""):e,a=parseInt(t.slice(0,2),16),l=parseInt(t.slice(2,4),16),i=parseInt(t.slice(4,6),16),c=t.length===8?Math.round(parseInt(t.slice(6,8),16)/255*100)/100:1,r=s!=null?Number(s):c;if(Number.isNaN(r)||r<0||r>1)throw new Error(`Invalid alpha value(0~1): ${s}`);return`rgba(${a}, ${l}, ${i}, ${r})`}
